import{z as l,x as d,o as s,c as i,q as o,j as n,D as A,d as E,s as r,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"浮点乘法与 FMA","description":"","frontmatter":{"title":"浮点乘法与 FMA","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fp-mul-fma.md","filePath":"cs/fp-mul-fma.md","lastUpdated":1791063341000}'),p={name:"cs/fp-mul-fma.md"};function m(c,a,f,C,D,u){const t=d("Mermaid");return s(),i("div",null,[a[2]||(a[2]=o('<h1 id="浮点乘法与-fma" tabindex="-1">浮点乘法与 FMA <a class="header-anchor" href="#浮点乘法与-fma" aria-label="Permalink to &quot;浮点乘法与 FMA&quot;">​</a></h1><div class="epigraph"><p>尾数相乘是无符号阵列，指数相加再减偏置；熔合乘加把乘积以全宽送进加法器，只舍入一次。</p><footer>—— 据 IEEE Std 754-2008；Patterson and Hennessy, Computer Organization and Design (RISC-V)；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/fp-adder">上一课</a>钉了对阶–尾数加–规格化。<a href="/cs/booth-multiplier">Booth</a> 与<a href="/cs/wallace-carry-save">华莱士</a>已给出整数乘的压缩树。缺口是把它们接进 754：符号 XOR、指数加、尾数乘，以及 2008 年写成基本运算的 <strong>FMA</strong>（fused multiply-add）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>规格化数乘：\\((\\pm m_1 2^{e_1})(\\pm m_2 2^{e_2})=\\pm (m_1 m_2)2^{e_1+e_2}\\)。尾数乘积在 \\([1,4)\\)，可能右规 1 位。指数要减偏置，并检测上溢/下溢。缺口不是再讲部分积，而是：<strong>乘积宽度</strong>（<code>binary32</code> 为 24×24→48 位）如何进舍入，以及 \\(a\\times b+c\\) 若先乘后加会舍入两次，FMA 要求一次。</p><p><span class="marginnote">数字实例感受「乘积宽度」：<code>binary32</code> 的两个 24 位尾数相乘得到 48 位精确积，而目标格式只装得下 24 位——超过一半的位都要挤进 GRS 参与舍入。同时 8 位指数相加后动态范围直接翻倍，这就是乘法路径必须单独检测上溢下溢的原因。</span></p><p>牛顿除<a href="/cs/newton-division">上一单元</a>依赖这条乘法器。本课把乘和 FMA 当作同一尾数树的两种收尾。</p><h3 id="fma-不是「乘加各做一次再省一个寄存器」" tabindex="-1">FMA 不是「乘加各做一次再省一个寄存器」 <a class="header-anchor" href="#fma-不是「乘加各做一次再省一个寄存器」" aria-label="Permalink to &quot;FMA 不是「乘加各做一次再省一个寄存器」&quot;">​</a></h3><p>语义差在舍入次数：<code>fma(a,b,c)</code> 的理想结果是 \\(ab+c\\) 在无限精度下再按模式映回格子，可以与 <code>fadd(fmul(a,b),c)</code> 差 1 ulp 或更多。把 FMA 理解成微结构融合（少一次写回），数值库与误差分析会对不齐。754-2008 把 FMA 列为推荐/要求的运算，RISC-V <code>F</code>/<code>D</code> 有 <code>fmadd</code> 等。</p><p><span class="marginnote">三位十进制的数字实例看清差别：算 \\(1.05\\times 1.05-1.10\\)。独立乘加先把 \\(1.1025\\) 舍成 \\(1.10\\)，再相减得 \\(0\\)；FMA 拿全宽的 \\(1.1025\\) 直接减，得 \\(0.00250\\)——恰好是真实的余数。两次舍入把信息抹掉了，一次舍入留住了它，这不是「快一点」，是语义不同。</span></p><p><span class="marginnote">Patterson/Hennessy 把浮点乘画成指数加与尾数乘两框。Hennessy/Patterson CA:AQA 讨论 FMA 对点积精度的影响。本课不进入张量核或混合精度训练。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>尾数：无符号阵列或 Booth+CSA，产出全宽积。指数：整数加，减 bias，再加规格化修正。FMA：全宽积与 \\(c\\) 的尾数对阶（移位量由指数差决定，积的二进制点在中间），走<a href="/cs/fp-adder">浮点加法器</a>的加减与舍入，但加法器宽度按积来。符号：乘为 XOR；加再按有效加减决定。</p>',13)),(s(),n(B,null,{default:A(()=>[r(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20MUL%5B%22%E5%B0%BE%E6%95%B0%E4%B9%98%E5%85%A8%E5%AE%BD%22%5D%20--%3E%20ALIGN%5B%22%E4%B8%8E%E5%8A%A0%E6%95%B0%E5%AF%B9%E9%98%B6%22%5D%0A%20%20ALIGN%20--%3E%20ADD%5B%22%E5%B0%BE%E6%95%B0%E5%8A%A0%E5%87%8F%22%5D%0A%20%20ADD%20--%3E%20RND%5B%22%E4%B8%80%E6%AC%A1%E8%88%8D%E5%85%A5%22%5D%0A%20%20MUL%20--%3E%20RMUL%5B%22%E7%8B%AC%E7%AB%8B%E4%B9%98%E6%B3%95%EF%BC%9A%E4%B9%98%E5%90%8E%E5%8D%B3%E8%88%8D%E5%85%A5%22%5D%0A%20%20RND%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%BC%82%E5%B8%B8%E6%97%97%E6%A0%87%22%5D%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[E("独立 "),e("code",null,"fmul"),E(" 在树之后就舍入到目标格式；FMA 跳过这次中间舍入。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"后课异常旗标要在乘、加、FMA 各路径上采样上溢、下溢、不精确。LZC 规格化对 FMA 的有效减同样关键。定点 DSP 乘加是另一套无指数的饱和通路，再后几课才对照，以免把 MAC 与 FMA 混名。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},[E("常见误区：DSP 手册里的 MAC 与 754 的 FMA 同名不同义——定点 MAC 没有指数、结果会饱和截断，也没有「一次舍入」的语义承诺。看到汇编里的 MAC 就当它是 "),e("code",null,"fma"),E("，误差分析会全盘对错对象。")])],-1)),(s(),n(B,null,{default:A(()=>[r(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%93%8D%E4%BD%9C%E6%95%B01%3A%E7%AC%A6%E5%8F%B7%20s1%2C%E6%8C%87%E6%95%B0%20e1%22%5D%20--%3E%20SG%5B%22%E7%AC%A6%E5%8F%B7%E4%BD%8D%3As1%20XOR%20s2%22%5D%0A%20%20B%5B%22%E6%93%8D%E4%BD%9C%E6%95%B02%3A%E7%AC%A6%E5%8F%B7%20s2%2C%E6%8C%87%E6%95%B0%20e2%22%5D%20--%3E%20SG%0A%20%20A%20--%3E%20EA%5B%22%E7%9C%9F%E6%8C%87%E6%95%B0%E7%9B%B8%E5%8A%A0%3Ae1%2Be2%22%5D%0A%20%20B%20--%3E%20EA%0A%20%20EA%20--%3E%20BIAS%5B%22%E7%BC%96%E7%A0%81%E6%97%B6%E5%87%8F%E5%8E%BB%E4%B8%80%E6%AC%A1%E5%81%8F%E7%BD%AE(%E5%A6%82%20127)%22%5D%0A%20%20BIAS%20--%3E%20NORM%5B%22%E5%B0%BE%E6%95%B0%E7%A7%AF%E2%89%A52%20%E5%88%99%E5%8F%B3%E8%A7%84%201%20%E4%BD%8D%2C%E6%8C%87%E6%95%B0%E8%A1%A5%20%2B1%22%5D%0A%20%20NORM%20--%3E%20CHK%7B%22%E6%96%B0%E6%8C%87%E6%95%B0%E8%BF%98%E8%A3%85%E5%BE%97%E4%B8%8B%E5%90%97%3F%22%7D%0A%20%20CHK%20--%20%22%E8%B6%85%E5%87%BA%E6%9C%80%E5%A4%A7%22%20--%3E%20OF%5B%22overflow%2C%E7%BB%93%E6%9E%9C%E8%B6%8B%20%C2%B1%E2%88%9E%22%5D%0A%20%20CHK%20--%20%22%E8%8C%83%E5%9B%B4%E5%86%85%22%20--%3E%20OUT%5B%22%E4%BA%A4%E7%BB%99%E8%88%8D%E5%85%A5%22%5D%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 GPU 张量核、不重写 Transformer 里的 SDPA。不把十进制 FMA 列入。软浮点用整数乘模拟同一语义，电路不在本课。</p><p>后课默认：浮点乘是尾数阵列加指数整数加；FMA 是全宽积再加、一次舍入。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>尾数乘复用整数压缩树；指数加偏置。</li><li>FMA 改变的是舍入次数，不只是吞吐。</li><li>牛顿除依赖这条乘法器。</li><li>出处：IEEE 754-2008；Patterson and Hennessy, COD (RISC-V)；Hennessy and Patterson, CA:AQA。</li></ul>',5))])}const M=l(p,[["render",m]]);export{h as __pageData,M as default};
